from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.pdfgen import canvas
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from pypdf import PdfReader

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'output/pdf/guia-caveman-rtk-ponytail-graphify.pdf'
OUT.parent.mkdir(parents=True, exist_ok=True)
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleX', fontName='Helvetica-Bold', fontSize=27, leading=32, textColor=colors.HexColor('#10334A'), spaceAfter=18))
styles.add(ParagraphStyle(name='SubX', fontName='Helvetica-Bold', fontSize=13, leading=17, textColor=colors.HexColor('#007C83'), spaceBefore=13, spaceAfter=7))
styles.add(ParagraphStyle(name='BodyX', fontName='Helvetica', fontSize=10.5, leading=15, spaceAfter=9))
styles.add(ParagraphStyle(name='CodeX', fontName='Courier', fontSize=9, leading=13, backColor=colors.HexColor('#EEF3F6'), borderPadding=9, spaceBefore=5, spaceAfter=13))
styles.add(ParagraphStyle(name='SmallX', fontName='Helvetica', fontSize=8.5, leading=12, textColor=colors.HexColor('#526574'), spaceAfter=7))
story=[]
def p(t): story.append(Paragraph(t, styles['BodyX']))
def h(t): story.append(Paragraph(t, styles['SubX']))
def code(t): story.append(Paragraph(escape(t).replace('\n','<br/>'),styles['CodeX']))
def title(n,t):
    if story: story.append(PageBreak())
    story.append(Paragraph(n.upper(),styles['SmallX']))
    story.append(Paragraph(t,styles['TitleX']))
def source(t,url): story.append(Paragraph(f'Fonte: <link href="{url}" color="#007C83">{escape(t)}</link>',styles['SmallX']))

title('Guia prático • Windows e assistentes de IA','Caveman, RTK,<br/>Ponytail e Graphify')
p('Como usar as quatro ferramentas no dia a dia, com prompts prontos para copiar e comandos de terminal. Preparado para Orleans Samai em 7 de setembro de 2026.')
h('Escolha pelo resultado que você quer')
for name,desc in [('Caveman','Respostas mais curtas, preservando o conteúdo técnico.'),('RTK','Menos saída de terminal enviada ao contexto da IA.'),('Ponytail','Soluções de código mais simples, com menos complexidade desnecessária.'),('Graphify','Um mapa persistente das relações entre arquivos, símbolos e conceitos.')]:
    p(f'<b>{name}</b> - {desc}')
h('O que já está instalado no seu computador')
p('No Codex: Caveman; Ponytail e suas cinco skills auxiliares; Graphify. No Windows: RTK <b>0.48.0</b> e Graphify <b>0.9.56</b>. O RTK recebeu configuração global para Codex por meio de AGENTS.md e RTK.md.')
p('As skills estão em <b>%USERPROFILE%\\.codex\\skills</b>. Os executáveis estão em <b>%USERPROFILE%\\.local\\bin</b>. A instalação foi feita para o seu usuário; outras IAs precisam da própria integração.')
h('Duas formas de interação')
p('<b>NA IA</b> significa enviar o texto no chat do assistente. <b>NO TERMINAL</b> significa executar no PowerShell, na pasta do projeto. Uma skill é um conjunto de instruções; uma CLI é um programa executável. Instalar uma skill não instala automaticamente todos os serviços do repositório.')
p('Neste ambiente foi instalada a skill Caveman, sem o proxy Caveman. Ponytail foi instalado como skills, sem os hooks do plugin completo. O Graphify está pronto para uso, mas nenhum grafo foi criado durante a instalação.')

title('01 • Comunicação','Caveman')
p('Use quando quiser uma explicação objetiva, um diagnóstico rápido ou um resumo de alterações. A proposta é encurtar a prosa, mantendo nomes de funções, caminhos, comandos e mensagens de erro exatos.')
h('No Codex: envie no chat')
code('Use a skill caveman no nível lite.\nExplique em português o erro abaixo e como corrigi-lo:\n[cole o erro aqui]')
p('Você também pode mencionar <b>$caveman</b> ao escrever o pedido. Usar o nome da skill em linguagem natural é uma alternativa quando o seletor de menções não aparecer.')
h('Escolha o nível')
p('<b>lite:</b> frases completas e concisas. Bom ponto de partida.<br/><b>full:</b> comunicação mais telegráfica.<br/><b>ultra:</b> compressão máxima; prefira para respostas simples.')
code('Use caveman full. Resuma as alterações feitas\nem no máximo 5 itens e inclua os testes executados.')
h('Como desligar')
code('Desative caveman. Volte ao estilo normal\ne explique cada etapa com detalhes.')
p('A skill prevê persistência na sessão até você mudar o nível ou pedir para parar. Os modos wenyan são variantes voltadas à escrita chinesa; para português, use lite, full ou ultra.')
h('Em outras IAs')
p('Após instalar a integração correspondente, os comandos documentados incluem <b>/caveman lite</b>, <b>/caveman full</b>, <b>/caveman ultra</b> e <b>/caveman off</b>. A disponibilidade como comando de menu depende do aplicativo.')
p('Em um chat sem skills, você pode pedir: “Responda de forma curta, preserve detalhes técnicos e explique ambiguidades”. Isso reproduz uma preferência de escrita, mas não instala Caveman.')
source('Caveman: skill e instalação','https://docs.caveman.so/docs/skill')

title('02 • Saída de terminal','RTK (rtk-ai/rtk)')
p('O RTK envolve comandos de desenvolvimento e apresenta uma saída filtrada. A economia ocorre quando o assistente executa comandos compatíveis por meio de rtk. A simples instalação não reduz todo o contexto nem garante uma porcentagem fixa de economia.')
h('Primeiro teste no PowerShell')
code('rtk --version\nrtk gain\nrtk --help')
p('No começo, gain pode informar que ainda não há dados. Isso é esperado. Dentro de um repositório Git, experimente:')
code('rtk git status\nrtk git diff\nrtk gain')
h('Peça à IA para usar')
code('Use RTK nos comandos compatíveis deste projeto.\nVerifique o estado do Git e execute os testes existentes.\nSe a saída filtrada não explicar uma falha,\nconsulte a saída completa do comando original.')
p('Os testes e ferramentas originais precisam existir. O RTK não instala Git, não cria testes e não substitui o compilador do projeto.')
h('Integração já feita no Codex')
code('rtk init --codex --global --show')
p('Essa configuração orienta o Codex por arquivos de instruções. Ela não instala um hook que reescreva todos os comandos automaticamente. Confirme nos comandos executados se o prefixo rtk está sendo usado.')
h('Configurar em outro assistente')
code('rtk init --help\nrtk init --agent cursor --global --dry-run\nrtk init --agent cursor --global')
p('O exemplo configura Cursor. Use apenas agentes listados no help da versão instalada. Para Claude Code, o comando documentado é <b>rtk init --global</b>; o suporte de hooks no Windows depende do ambiente. A documentação recomenda WSL para suporte completo de hooks.')
source('RTK: instalação e Windows','https://www.rtk-ai.app/docs/getting-started/installation/')

title('03 • Código simples','Ponytail')
p('Use ao implementar ou revisar código. Ponytail incentiva aproveitar recursos nativos, bibliotecas padrão e dependências já existentes, evitando criar abstrações que a tarefa não exige.')
h('Comece no Codex')
code('Use a skill ponytail no nível lite.\nImplemente [recurso] com a solução mais simples\nque atenda aos requisitos. Preserve as validações\ne execute os testes relevantes existentes.')
p('<b>lite:</b> atende ao pedido e sugere alternativas simples.<br/><b>full:</b> aplica com mais rigor a busca pela menor solução suficiente.<br/><b>ultra:</b> questiona mais os requisitos e prioriza remover complexidade.')
h('As cinco skills auxiliares instaladas')
p('<b>ponytail-review:</b> revisão de alterações em busca de complexidade desnecessária.<br/><b>ponytail-audit:</b> avaliação de todo o repositório.<br/><b>ponytail-debt:</b> reúne comentários ponytail: sobre atalhos e pendências.<br/><b>ponytail-gain:</b> apresenta os resultados dos benchmarks do projeto.<br/><b>ponytail-help:</b> mostra a referência de comandos.')
code('Use ponytail-review nas alterações atuais.\nListe o que pode ser simplificado, com arquivo\ne motivo. Faça apenas a revisão, sem editar.')
code('Use ponytail-audit neste projeto. Priorize três\nsimplificações de baixo risco e explique o impacto.')
p('<b>Atenção ao gain:</b> os números apresentados são de benchmarks do Ponytail; não medem automaticamente a economia deste projeto ou da sua conta.')
h('Desligar e usar em outros assistentes')
code('Desative ponytail e volte ao modo normal.')
p('Com a integração apropriada, Claude Code e OpenCode documentam comandos como <b>/ponytail lite</b> e <b>/ponytail-review</b>. No Codex, peça pelo nome ou mencione a skill pelo seletor. Configurações de hooks e ativação automática do plugin completo não devem ser presumidas na instalação apenas das skills.')
source('Ponytail: repositório e integrações','https://github.com/DietrichGebert/ponytail')

title('04 • Entender o projeto','Graphify')
p('Graphify transforma conteúdo em um grafo consultável. Ajuda a localizar partes centrais, relacionar módulos e investigar dependências. As conexões podem ser extraídas ou inferidas; confirme decisões importantes no código original.')
h('Criar o primeiro mapa: envie à IA')
code('Use a skill graphify na pasta atual.\nGere o grafo do projeto e explique os principais\nmódulos em português. Não altere o código-fonte.')
p('No Codex, também é possível mencionar <b>$graphify</b>. A documentação do projeto usa <b>/graphify .</b> nos assistentes com comandos de barra. Esse texto é um pedido à IA, não um comando PowerShell.')
h('Arquivos gerados')
p('<b>graphify-out/graph.html:</b> visualização no navegador.<br/><b>graphify-out/graph.json:</b> dados do grafo para consultas.<br/><b>graphify-out/GRAPH_REPORT.md:</b> relatório legível.')
h('Consultar um mapa existente no terminal')
code('graphify query "Como funciona a navegação?"\ngraphify explain "NomeRealDoSimbolo"\ngraphify path "SimboloA" "SimboloB"')
p('Execute na raiz do projeto que contém graphify-out. Substitua os nomes de exemplo pelos símbolos reais do grafo. Se não houver correspondência, veja o relatório ou a visualização para encontrar os nomes disponíveis.')
h('Atualizar depois de mudar o código')
code('graphify update .')
p('Ou peça à IA: “Use Graphify para atualizar o mapa após as alterações e identificar os módulos afetados”. A criação inicial pode levar mais tempo que consultas posteriores. Arquivos multimídia e análises semânticas podem exigir dependências ou um backend de IA adicional.')
h('Registrar em outra IA, no mesmo computador')
code('graphify install --platform cursor\ngraphify install --platform gemini\ngraphify install --platform codex')
p('Escolha somente o aplicativo que deseja configurar. Consulte <b>graphify install --help</b> ou <b>graphify --help</b> para as opções da versão instalada.')
source('Graphify: início rápido','https://graphify.com/docs')

title('05 • Outros aplicativos','Como levar para outras IAs')
p('As ferramentas se integram ao aplicativo que executa a IA. Usar o mesmo modelo em dois aplicativos não compartilha automaticamente suas skills, arquivos locais ou comandos de terminal.')
h('Claude Code: Caveman e Ponytail')
p('No terminal, com Claude Code já instalado, os projetos documentam:')
code('claude plugin marketplace add JuliusBrussee/caveman\nclaude plugin install caveman@caveman\nclaude plugin marketplace add DietrichGebert/ponytail\nclaude plugin install ponytail@ponytail')
p('Depois, abra uma nova sessão e use os comandos das skills. Esses comandos instalam plugins mais amplos; não foram executados durante a instalação anterior no seu computador.')
h('Gemini CLI: extensões')
code('gemini extensions install https://github.com/JuliusBrussee/caveman\ngemini extensions install https://github.com/DietrichGebert/ponytail')
p('Para Graphify, use o registro da página anterior. Para RTK, confira <b>rtk init --gemini --help</b> antes de configurar a integração.')
h('Cursor e outros agentes compatíveis com skills')
p('Caveman e Ponytail podem ser distribuídos pelo instalador de skills. No terminal, os comandos abaixo abrem o fluxo de instalação; selecione o agente e o escopo desejados:')
code('npx skills add JuliusBrussee/caveman\nnpx skills add DietrichGebert/ponytail')
p('Esse método requer Node.js/npm. Sem escopo global, os arquivos podem ser instalados apenas no projeto atual. Confirme o destino mostrado pelo instalador antes de concluir.')
h('Chats sem acesso ao seu computador')
p('Em uma conversa que não oferece acesso aos seus arquivos e terminal, use prompts de concisão ou simplicidade e envie trechos de código ou o relatório do Graphify. A instalação local, sozinha, não fornece RTK ou Graphify a esse chat. Para execução real, é necessário um ambiente conectado e compatível.')
source('Caveman: opções de instalação','https://docs.caveman.so/docs/skill')
source('Ponytail: opções por assistente','https://github.com/DietrichGebert/ponytail')

title('06 • Referência diária','Use as quatro em conjunto')
h('Um pedido pronto para copiar no Codex')
code('Use caveman lite para responder com clareza e brevidade.\nUse Graphify para entender os módulos envolvidos.\nUse ponytail lite para escolher a solução mais simples.\nUse RTK nos comandos de terminal compatíveis.\n\nTarefa: [descreva a alteração].\nPreserve os requisitos e as validações existentes.\nAo terminar, resuma alterações, testes e limitações.')
p('Fluxo sugerido: entender com Graphify, implementar com Ponytail, executar comandos compatíveis com RTK e comunicar o resultado com Caveman. Não é necessário acionar todos para uma pergunta simples.')
h('Se algo não funcionar')
p('<b>Skill não aparece:</b> tente pedir pelo nome; abra uma nova tarefa ou reinicie o Codex se necessário. As skills instaladas já foram reconhecidas neste ambiente.')
p('<b>Comando não reconhecido:</b> abra um novo terminal. Para testar sem depender do PATH, use:')
code('& "$env:USERPROFILE\\.local\\bin\\rtk.exe" --version\n& "$env:USERPROFILE\\.local\\bin\\graphify.exe" --version')
p('<b>Graphify sem grafo:</b> peça primeiro a criação pela skill, na pasta correta. Instalar o programa não cria o mapa.<br/><b>RTK sem economia registrada:</b> confira se comandos foram executados com rtk; a configuração do Codex é baseada em instruções.<br/><b>Resposta curta demais:</b> reduza Caveman para lite ou desligue.<br/><b>Ponytail simplificou demais:</b> explicite os requisitos e peça para preservar comportamento e validações.')
h('Fontes e escopo de verificação')
p('Guia baseado na instalação local, no help dos executáveis e nas referências dos mantenedores consultadas em 07/09/2026. Os exemplos de integração com outras IAs são instruções para uso futuro; não representam instalações ou testes feitos nesses aplicativos.')
source('OpenAI: skills e invocação','https://developers.openai.com/codex/skills')
source('Caveman','https://docs.caveman.so/docs/skill')
source('RTK','https://github.com/rtk-ai/rtk')
source('Ponytail','https://github.com/DietrichGebert/ponytail')
source('Graphify','https://github.com/Graphify-Labs/graphify')

def footer(c,doc):
    w,h=doc.pagesize
    c.setFillColor(colors.HexColor('#007C83')); c.rect(0,h-9,w,9,fill=1,stroke=0)
    c.setStrokeColor(colors.HexColor('#D7E2E7')); c.line(44,39,w-44,39)
    c.setFont('Helvetica',8); c.setFillColor(colors.HexColor('#526574'))
    c.drawString(44,25,'GUIA PRÁTICO | IA + FERRAMENTAS | 07.09.2026')
    c.drawRightString(w-44,25,str(doc.page))

doc=SimpleDocTemplate(str(OUT),pagesize=(595.28,841.89),rightMargin=44,leftMargin=44,topMargin=39,bottomMargin=53,title='Como usar Caveman, RTK, Ponytail e Graphify nas IAs',author='Guia preparado para Orleans Samai')
doc.build(story,onFirstPage=footer,onLaterPages=footer)
r=PdfReader(OUT)
print(OUT)
print('Pages:',len(r.pages))
for i,page in enumerate(r.pages): print(i+1,len(page.extract_text()),page.extract_text()[:65].replace('\n',' '))
